// Rotativo sem planilha: a lista (quem está ligado, ordem e o nome que vai no
// "nome atendente") fica na memória deste fluxo. Liga/desliga na tela Rotativo
// do Setup da Conta. Esta é a lista de quando o fluxo foi gerado:
const INICIAL = ["__ORDEM_ROTATIVO__"];

const memoria = $getWorkflowStaticData('global');
const lista = Array.isArray(memoria.lista) ? memoria.lista : INICIAL;
const fila = lista.filter((p) => p.ligado && p.nome);
if (!fila.length) throw new Error('Ninguém ligado no rotativo: ligue alguém na tela Rotativo do Setup da Conta.');

// A vez fica guardada na memória do fluxo (só com o fluxo ativo; no teste manual começa do primeiro).
const ids = fila.map((p) => p.id);
const proximo = fila[(ids.indexOf(memoria.ultimo) + 1) % fila.length];
memoria.ultimo = proximo.id;

return [{ json: { userId: proximo.id, nome: proximo.nome, posicao: ids.indexOf(proximo.id) + 1, total: fila.length } }];

